  changed() {

    const model = this.gearRatio.carFactoryNames.find(e => e.id == this.carFactoryId);

    this.updateForm4.setValue({
      id: this.carFactoryId,
      name: model.name,
      isDelete: model.isDelete
    });

    this.updateForm3.setValue({
      id: '',
      name: '',
      isDelete: false
    });
  }

  changed2() {

    const model = this.gearRatio.carModelNames.find(e => e.id == this.carModelId);

    this.updateForm3.setValue({
      id: this.carModelId,
      name: model.name,
      isDelete: model.isDelete
    });
  }

  changed3() {

    const model = this.gearRatio.gearBoxModelNames.find(e => e.id == this.gearId);

    this.updateForm2.setValue({
      id: this.gearId,
      name: model.name,
      isDelete: model.isDelete,
      g1: model.g1,
      g2: model.g2,
      g3: model.g3,
      g4: model.g4,
      g5: model.g5,
      g6: model.g6,
      g7: model.g7,
      g8: model.g8,
      rev: model.rev,
      def: model.def,
    });
  }

  onAddCourseId(id) {

    this.courseIds.push(+id);
  }

  removeId(index: number): void {

    this.courseIds.splice(+index, 1);
  }

  onDelete(index: number | string): void {

    this.selectedIndex = +index;

    SharedIonic.loading(this.loadingController);

    this.siteService.RemoveTunerPlus(this.tunerPluses[this.selectedIndex].id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          this.updateForm.setValue({
            id: '',
            courseId: '',
            tunerPlusId: '',
            name: '',
            isActive: false,
            isFree: false,
            isVip: false
          });
          this.tunerPluses.splice(this.selectedIndex, 1);
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onUpdate() {

    if (this.updateForm.valid || this.selectedIndex != 0 && this.courseIds.length != 0) {

      SharedIonic.loading(this.loadingController);

      const model = new TunerPlusCourseViewModel(
        this.updateForm.value.id,
        this.updateForm.value.courseId,
        this.updateForm.value.tunerPlusId,
        this.courseIds,
        this.updateForm.value.name,
        this.updateForm.value.isActive,
        this.updateForm.value.isFree,
        this.updateForm.value.isVip
      );

      this.siteService.AddOrUpdateTunerPlus(
        model
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.updateForm.setValue({
              id: '',
              courseId: '',
              tunerPlusId: '',
              name: '',
              isActive: false,
              isFree: false,
              isVip: false
            });
            const index = this.tunerPluses.findIndex(e => e.id == model.id);

            if (index == -1) {

              this.courseIds = [];
              this.getData();
            } else {
              this.tunerPluses[index].courseId = model.courseId;
              this.tunerPluses[index].isActive = model.isActive;
              this.tunerPluses[index].isFree = model.isFree;
              this.tunerPluses[index].isVip = model.isVip;
              this.tunerPluses[index].name = model.name;
              this.tunerPluses[index].courseIds = [...this.courseIds];
              this.courseIds = [];
            }
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  onAdd() {

    if (this.addForm.valid && this.courseIds.length != 0) {

      SharedIonic.loading(this.loadingController);

      const newModel = new TunerPlusCourseViewModel(
        0,
        0,
        0,
        this.courseIds,
        this.addForm.value.name,
        this.addForm.value.isActive,
        this.addForm.value.isFree,
        this.addForm.value.isVip
      );

      this.siteService.AddOrUpdateTunerPlus(
        newModel
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.addForm.setValue({
              name: '',
              isActive: false,
              isFree: false,
              isVip: false
            });
            SharedIonic.successToast(this.toastController);

            this.courseIds = [];
            this.getData();
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

